/**
 * Interface representing an asset entry in the manifest file.
 */
export interface AssetManifestEntry {
    /** The Roblox asset ID (without the rbxassetid:// prefix) */
    assetId: string;
    /** Optional description for the asset */
    description?: string;
}
/**
 * Interface representing the structure of an asset manifest file.
 * Maps file paths (relative to the assets directory) to asset information.
 */
export interface AssetManifest {
    [filePath: string]: AssetManifestEntry;
}
/**
 * Loads an asset manifest from a JSON file.
 *
 * @param manifestPath - Path to the manifest file
 * @returns The parsed manifest object, or an empty object if file doesn't exist or has errors
 */
export declare function loadAssetManifest(manifestPath: string): AssetManifest;
/**
 * Gets the asset ID for a given file path from the manifest.
 *
 * @param manifest - The loaded asset manifest
 * @param filePath - Absolute path to the asset file
 * @param assetDirectory - The base assets directory path
 * @returns The asset ID if found in manifest, undefined otherwise
 */
export declare function getAssetIdFromManifest(manifest: AssetManifest, filePath: string, assetDirectory: string): string | undefined;
